css:
.rsr-root[data-theme='simple'] { padding: 0; }
.rsr-root[data-theme='simple'] .container { max-width: none; padding-left: 46px; padding-right: 46px; }
.rsr-root[data-theme='simple'] .top .container { padding-top: 30px; padding-bottom: 8px; }

.rsr-root[data-theme='simple'] {background: #fff;
  font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
  font-size: 14px;
  color: rgba(0, 0, 0, 0.882353);
  line-height: 20px;
  margin: 0; }
.rsr-root[data-theme='simple'] em {color: #999; }
.rsr-root[data-theme='simple'] p {line-height: 1.4; }
.rsr-root[data-theme='simple'] ul {margin: 10px 0 20px 0;
  padding-left: 20px; }
.rsr-root[data-theme='simple'] blockquote {margin: 0;
  margin-bottom: 1em; }
.rsr-root[data-theme='simple'] .item {margin-bottom: 20px; }
.rsr-root[data-theme='simple'] .container {margin: 0 auto;
  max-width: 420px;
  padding: 0 30px; }
.rsr-root[data-theme='simple'] .top {padding-top: 20px;
  background-color: #EEE;
  height: 40px; }
.rsr-root[data-theme='simple'] .center-text {text-align: center; }
.rsr-root[data-theme='simple'] .profile-pic {float: left;
  width: 80px;
  height: 80px;
  background-size: 80px;

  -moz-border-radius: 50%; 
  -webkit-border-radius: 50%; 
  border-radius: 50%;
  border-color: #FFF;
  border-style: solid;
  border-width: 4px; }
.rsr-root[data-theme='simple'] .name-title {float: left;
  margin-left: 10px; }
.rsr-root[data-theme='simple'] .name {font-size: 25px;
  line-height: 40px;
  color: rgba(0,0,0,0.88);
  font-weight: 400;
  margin: 4px 0 0 0; }
.rsr-root[data-theme='simple'] .job-title {font-size: 17px;
  color: rgba(0,0,0,0.6); }
.rsr-root[data-theme='simple'] .bio {margin: 20px 0; }
.rsr-root[data-theme='simple'] .heading {text-transform: uppercase;
  font-weight: 500;
  margin: 20px 0 10px 0;
  color: #F05C5C; }
.rsr-root[data-theme='simple'] .item .heading {text-transform: none;
  font-weight: 700; }
.rsr-root[data-theme='simple'] .website {font-weight: 300; }
.rsr-root[data-theme='simple'] .profiles .website {margin-left: 5px; }
.rsr-root[data-theme='simple'] .label {display: inline-block;
  font-weight: 700;
  line-height: 1.5em; }
.rsr-root[data-theme='simple'] .contact .label {width: 75px; }
.rsr-root[data-theme='simple'] .clearfix {clear: both; }
.rsr-root[data-theme='simple'] .summary {margin: 15px 0 20px 0; }
.rsr-root[data-theme='simple'] .highlights {font-weight: 300; }
.rsr-root[data-theme='simple'] .details {padding-left: 10px;
  border-left-style: solid;
  border-left-width: 2px;
  border-left-color: #999; }
.rsr-root[data-theme='simple'] .skills .level {font-size: 0.8em;
  font-weight: 300;
  color: #666; }
.rsr-root[data-theme='simple'] .skills .item {margin-bottom: 10px; }
.rsr-root[data-theme='simple'] .skills ul {margin-bottom: 10px; }
.rsr-root[data-theme='simple'] .footer {margin-top: 50px;
  height: 1px; }
